// ln-наезд камеры по кадрам (накопленный) — по нему скролл ведёт камеру равномерно через оба клипа
function zoomOf(flow) { const z = [0]; for (const [k] of flow) z.push(z[z.length - 1] + Math.log(Math.max(1, k))); return z; }
